import SwiftUI

/// Small rules independent of UI and networking, kept separate so `tests/AppRulesTests.swift` can compile and verify them directly.
enum AppRules {
    /// Hex representation of the APNs device token
    static func hexString(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    /// Notification text is generated by the server in this language; the App only has Chinese and English, other languages use English
    static func pushLanguage(_ localization: String?) -> String {
        localization?.hasPrefix("zh") == true ? "zh" : "en"
    }

    /// Effect of foreground/background switches on the realtime connection. Only disconnect when truly entering background;
    /// stay connected when inactive (pulling down Notification Center or Control Center, incoming-call banner, photo/camera permission prompt, app switcher),
    /// otherwise every time would disconnect, re-register the terminal, reconnect and do a full refresh.
    enum ForegroundChange: Equatable {
        case none
        /// Entering background: disconnect MQTT, stop the activity timer
        case leave
        /// Back from background: reconnect, catch up on data, check forced update
        case resume
    }

    struct ForegroundTracker {
        private(set) var inBackground = false

        mutating func change(to phase: ScenePhase) -> ForegroundChange {
            switch phase {
            case .background:
                guard !inBackground else { return .none }
                inBackground = true
                return .leave
            case .active:
                guard inBackground else { return .none }
                inBackground = false
                return .resume
            default:
                return .none
            }
        }
    }

    /// When the server has MQTT off, ask for credentials again after this long, so it can switch over once enabled without waiting for a foreground/background switch
    static let mqttDisabledRecheckSeconds: Double = 300

    /// Backoff after connection failure: 1, 2, 4… up to 30 seconds
    static func mqttRetryDelay(attempts: Int) -> Double {
        min(30, pow(2, Double(min(max(attempts, 0), 5))))
    }

    /// Terminal name: since iOS 16, without a special entitlement `UIDevice.name` only returns the model ("iPhone"/"iPad"), so all phones get the same name.
    /// In that case use "<account name>'s iPhone"; if the system provides a user-chosen name (different from the model), use it as is.
    /// Display only: the server identifies terminals by owner + fingerprint, so renaming doesn't affect identification.
    static func terminalName(deviceName: String, model: String, owner: String,
                             format: (String, String) -> String) -> String {
        let device = deviceName.trimmingCharacters(in: .whitespacesAndNewlines)
        let owner = owner.trimmingCharacters(in: .whitespacesAndNewlines)
        if !device.isEmpty && device != model { return device }
        return owner.isEmpty ? model : format(owner, model)
    }

    /// Group selections include the owners of all selected Agents.
    static func withAgentOwners(_ ids: [String], currentUser: String?, owners: [String: String]) -> [String] {
        var result = ids
        for id in ids {
            if let owner = owners[id], owner != currentUser, !result.contains(owner) { result.append(owner) }
        }
        return result
    }

    static func canJoin(_ ids: [String], currentUser: String?, owners: [String: String], shares: [String: [String]]) -> Bool {
        let members = withAgentOwners(ids, currentUser: currentUser, owners: owners) + [currentUser ?? ""]
        let agents = members.filter { owners[$0] != nil }
        let humans = members.filter { owners[$0] == nil }
        return agents.allSatisfy { agent in humans.allSatisfy { $0 == owners[agent] || (shares[agent] ?? []).contains($0) } }
    }

    static func showsConversation(shared: Bool, permanent: Bool, sharedOnly: Bool, permanentOnly: Bool) -> Bool {
        (!permanentOnly && !sharedOnly) || (sharedOnly && shared) || (permanentOnly && !shared && permanent)
    }
}
